class AirportSystem_AutoGenerated {
  /*find staff with provided id and boss with provided boss id, if the staff not exist,
   *create a new staff with provided info, and set the staff's boss to the boss you find*/
  createStaff(
    id: number,
    name: string,
    pswd: string,
    phone: string,
    role: number,
    bossid: number,
  ): boolean {
    /*Definition Start*/
    let staff: Staff = l({
      logic: () =>
        getRepository(Staff).find(
          (s: any) =>
            l({
              logic: () => s.Id === id,
              description: "s.Id=id",
            }).build().pass,
        ),
      description: "Staff.allInstance()->any(s|s.Id=id)",
    }).build().pass;
    let boss: Staff = l({
      logic: () =>
        getRepository(Staff).find(
          (s: any) =>
            l({
              logic: () => s.Id === bossid,
              description: "s.Id=bossid",
            }).build().pass,
        ),
      description: "Staff.allInstance()->any(s|s.Id=bossid)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(staff),
        description: "staff.oclIsUndefined()",
      }).build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newStaff: Staff;
    return l({
      execute: () => (newStaff = new Staff()),
      description: "newStaff.oclIsNew()",
    })
      .and({
        execute: () => getRepository(Staff).push(newStaff),
        description: "Staff.allInstance()->includes(newStaff)",
      })
      .and({
        execute: () => (newStaff.Id = id),
        description: "newStaff.Id=id",
      })
      .and({
        execute: () => (newStaff.Name = name),
        description: "newStaff.Name=name",
      })
      .and({
        execute: () => (newStaff.Password = pswd),
        description: "newStaff.Password=pswd",
      })
      .and({
        execute: () => (newStaff.Phone = phone),
        description: "newStaff.Phone=phone",
      })
      .and({
        execute: () => (newStaff.Role = role),
        description: "newStaff.Role=role",
      })
      .and({
        execute: () => (newStaff.Boss = boss),
        description: "newStaff.Boss=boss",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { AirportSystem_AutoGenerated };

